/**
 * Seeds demo data through the [IncidentRepository] interface, so the very same function works for
 * the in-memory fake and for a persistent (Exposed) implementation.
 *
 * Schema creation, transaction handling and id generation are deliberately left to the
 * implementation. Seeding is idempotent: an already populated repository is left untouched.
 */
suspend fun IncidentRepository<Long>.seedDemoData(incidents: List<Incident>): List<Incident> {
    if (findAll().isNotEmpty()) return emptyList()
    return saveAll(incidents)
}

/**
 * Convenience overload that resolves the reporters from an already seeded [userRepository],
 * so seed the users first.
 */
suspend fun IncidentRepository<Long>.seedDemoData(userRepository: UserRepository<Long>): List<Incident> {
    val idsByUsername = userRepository.findAll().associate { it.username to it.id }
    return seedDemoData(demoIncidents { username -> idsByUsername[username] })
}
